import{_ as t,o as n,c as o,a6 as i}from"./chunks/framework.CCKCzdWs.js";const p=JSON.parse(`{"title":"Deployed environments","description":"How Piwi reads a Playwright run against a deployed environment, whose application is not the tests' commit: the deployed commit, the application's changes, the first failing deploy and what bisect can find.","frontmatter":{"title":"Deployed environments","description":"How Piwi reads a Playwright run against a deployed environment, whose application is not the tests' commit: the deployed commit, the application's changes, the first failing deploy and what bisect can find.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/deployed-environments.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/deployed-environments.html"}],["meta",{"property":"og:title","content":"Deployed environments | Piwi for Playwright"}],["meta",{"property":"og:description","content":"How Piwi reads a Playwright run against a deployed environment, whose application is not the tests' commit: the deployed commit, the application's changes, the first failing deploy and what bisect can find."}]]},"headers":[],"relativePath":"features/deployed-environments.md","filePath":"features/deployed-environments.md","lastUpdated":1795129570000}`),a={name:"features/deployed-environments.md"};function r(s,e,l,h,d,m){return n(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="deployed-environments" tabindex="-1">Deployed environments <a class="header-anchor" href="#deployed-environments" aria-label="Permalink to &quot;Deployed environments&quot;">​</a></h1><p>A deployed environment, such as Staging or Production, runs whatever version of the application was last deployed there, whatever the commit of the tests that run against it. Piwi reads a run of one as two versions: the tests&#39;, the run&#39;s commit, and the application&#39;s, its <strong>deployed commit</strong>. An environment, a discovered one included, is built from the checkout until a project admin turns its <strong>Built from the checkout</strong> setting off (<a href="./environments.html#built-from-the-checkout-or-deployed">Environments</a>): only then is it deployed. The setting also tells an agent, through the MCP tool <code>list_environments</code>, whether a failure&#39;s commit holds the code that ran.</p><h2 id="the-deployed-commit" tabindex="-1">The deployed commit <a class="header-anchor" href="#the-deployed-commit" aria-label="Permalink to &quot;The deployed commit&quot;">​</a></h2><p>The first source that names one wins:</p><ol><li><strong>The server under test</strong> reports the commit it was built from (<code>appCommit</code>), through an <a href="/guide/backend-logs.html#server-environment">instrumentation package</a>.</li><li><strong>A deploy marker</strong> of the environment carries the commit its pipeline deployed (<a href="./timeline-markers.html#recording-deploys-from-ci">Recording deploys from CI</a>): a run takes the latest one before it started.</li></ol><p>With neither, the deployed version is unknown, and every view below says it may differ from the run&#39;s commit.</p><p>The application is assumed to live in the project&#39;s repository, as in a monorepo: the commits between two deployed commits are read there, with the project&#39;s <a href="/guide/source-control.html">source control</a> credential. For an application kept in another repository, only its deployed commits mean something: the range and the suspect lines look for them in the project&#39;s repository.</p><h2 id="what-changes-for-a-run-of-a-deployed-environment" tabindex="-1">What changes for a run of a deployed environment <a class="header-anchor" href="#what-changes-for-a-run-of-a-deployed-environment" aria-label="Permalink to &quot;What changes for a run of a deployed environment&quot;">​</a></h2><ul><li><strong>The run page</strong> names the deployed commit in its facts line (<code>app a1b2c3d</code>), and <strong>Details → Application</strong> says where it comes from.</li><li><strong>The Changes tab</strong> adds a <strong>Deployed to Staging</strong> card beside the tests&#39; commits: the deployed commit of both runs, the application&#39;s commits between them, and the environment&#39;s deploy markers between the two runs (<a href="./run-changes.html">What changed in a run</a>).</li><li><strong><a href="./server-coverage.html#suspect-lines">Suspect lines</a></strong> are read on the application&#39;s range, from the last green run&#39;s deployed commit to the failing run&#39;s, since the coverage is the deployed application&#39;s. With the run&#39;s deployed commit unknown, they are read on the tests&#39; range, and say so.</li><li><strong><a href="./uncovered-changes.html">Uncovered changes</a></strong>: what the run reached of the application is the deployed version&#39;s. When that is not the change&#39;s head, or is unknown, the answer and the pull request comment say so, and the reach counts as any run&#39;s.</li><li><strong>The <a href="./ai-diagnosis.html">AI diagnosis</a></strong> gets an Environment Under Test section: the environment&#39;s name and description, whether it is built from the checkout, the deployed commits, the application&#39;s range and the deploy markers.</li><li><strong>Bisect</strong> walks the tests&#39; commits, so against a deployed environment it can find a change of the tests, never one of the application. The Reproduce section and the <a href="./fix-plans.html">fix plan</a> list the deploys between the last passing run and the failing one instead.</li></ul><h2 id="the-first-failing-deploy" tabindex="-1">The first failing deploy <a class="header-anchor" href="#the-first-failing-deploy" aria-label="Permalink to &quot;The first failing deploy&quot;">​</a></h2><p>A <a href="./failure-clusters.html">failure cluster</a> first seen in a deployed environment names its <strong>first failing deploy</strong>: the deploy marker between the last run of that environment where one of its tests passed and the run it first failed in. When several fall there, the latest is the one the first failing run tested. When none does, the line says that no deploy happened since the last pass: as far as the markers tell, the application did not change, so the tests, the data or the infrastructure did.</p><p>The cluster&#39;s <strong>What changed</strong> line leads with it, the execution page&#39;s since line names it (&quot;New regression after Staging deploy 7 (a1b2c3d) on Staging&quot;), and the AI diagnosis and the MCP tool <code>get_cluster</code> (<code>firstFailingDeploy</code>) carry it with both runs&#39; deployed commits.</p><h2 id="an-environment-s-activity" tabindex="-1">An environment&#39;s activity <a class="header-anchor" href="#an-environment-s-activity" aria-label="Permalink to &quot;An environment&#39;s activity&quot;">​</a></h2><p>In <strong>Project → Settings → Environments</strong>, each environment opens its activity: its last run, its last <a href="./environment-incidents.html">environment incident</a>, its deploy markers with their commits, and for a deployed one the commits and application versions its recent runs ran against, each with where the commit came from.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>A deploy marker counts for the environment it names. A marker with no environment counts for none.</li><li>A deployed commit from a deploy marker is the commit posted, not proof of what the servers run: a server that reports its own wins over the marker.</li><li>Bisect never walks the history of an application kept in another repository.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./environments.html">Environments</a></li><li><a href="./timeline-markers.html">Timeline markers</a></li><li><a href="./run-changes.html">What changed in a run</a></li><li><a href="./failure-clusters.html">Failure clusters</a></li><li><a href="/guide/backend-logs.html">Backend instrumentation</a></li><li><a href="/guide/concepts.html#deployed-environment">Glossary: deployed environment</a></li></ul>',18)])])}const f=t(a,[["render",r]]);export{p as __pageData,f as default};
